 publish:expectedRevision=>MW_REQUEST('/publish','POST',{expectedRevision}),
 newMenu:(id,name)=>({id,name,description:null,type:'main',active:true,translations:{},sections:[]}),
 newSection:(id,name)=>({id,name,description:null,parentSectionId:null,active:true,translations:{},items:[]}),
 newItem:(id,name)=>({id,name,description:null,price:0,available:true,displayMode:'normal',variants:[],translations:{},allergens:[],tags:[],additives:[]}),
 createVersion:(menuId,expectedRevision,label='Versione manuale')=>MW_REQUEST('/versions','POST',{expectedRevision,label}),
 listVersions:async()=> (await MW_REQUEST('/versions')).data,
 compareVersion:async(menuId,id)=>(await MW_REQUEST('/versions/'+encodeURIComponent(id)+'/diff')).data,
 downloadQr:async(menuId,format='png')=>{const query=new URLSearchParams({format});if(menuId)query.set('menuId',menuId);const r=await fetch('/api/menu-workspace/qr?'+query,{credentials:'include'});if(!r.ok){const data=await r.json().catch(()=>null);throw new Error(data?.error?.message||'QR non disponibile: pubblica il menu prima del download');}return r.blob();},
 restoreVersion:(menuId,id,expectedRevision)=>MW_REQUEST('/versions/'+encodeURIComponent(id)+'/restore','POST',{expectedRevision}),
 previewImport:body=>MW_REQUEST('/import/preview','POST',body),
 previewTranslation:body=>MW_REQUEST('/translate/preview','POST',body),
 listPresets:async()=>(await MW_REQUEST('/presets')).data,
 createPreset:(name,design)=>MW_REQUEST('/presets','POST',{name,design}),
 deletePreset:id=>MW_REQUEST('/presets/'+encodeURIComponent(id),'DELETE'),
 listCatalogs:async()=>(await MW_REQUEST('/catalogs')).data,
 listAssets:async()=>await MW_REQUEST('/assets'),
 uploadAsset:file=>{const form=new FormData();form.append('file',file);return MW_REQUEST('/assets','POST',form);},
 deleteAsset:id=>MW_REQUEST('/assets/'+encodeURIComponent(id),'DELETE'),
 renderPdf:async(body)=>{const r=await fetch('/api/menu-workspace/pdf',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error('Generazione PDF non riuscita');return r.blob();},
 textStyleFields:[MW_FIELD('fontSize','Dimensione testo','number'),MW_FIELD('color','Colore','color'),MW_FIELD('bold','Grassetto','boolean'),MW_FIELD('italic','Corsivo','boolean'),MW_FIELD('align','Allineamento','text',{options:['left','center','right']})],
 styleFields:[MW_FIELD('font','Font','text',{options:['sans','serif','mono','poppins','staatliches','amaranth','italiana']}),MW_FIELD('layout','Layout','text',{options:['list','cards','compact']}),...['background','text','primary','categoryBackground','categoryText'].map(k=>MW_FIELD(k,{background:'Sfondo',text:'Testo',primary:'Colore principale',categoryBackground:'Sfondo categorie',categoryText:'Testo categorie'}[k],'color')),MW_FIELD('fontSize','Dimensione testo (px)','number'),MW_FIELD('spacing','Spaziatura (px)','number'),MW_FIELD('imageShape','Forma immagini','text',{options:['square','rounded','circle']}),...['showImages','showPrices','showDescriptions','showAllergens'].map(k=>MW_FIELD(k,{showImages:'Mostra immagini',showPrices:'Mostra prezzi',showDescriptions:'Mostra descrizioni',showAllergens:'Mostra allergeni'}[k],'boolean')),MW_FIELD('headerTitle','Titolo header'),MW_FIELD('headerDescription','Descrizione header'),MW_FIELD('logoUrl','Logo URL','text',{nullable:true}),MW_FIELD('coverUrl','Copertina URL','text',{nullable:true}),...['borderWidth','borderRadius','categoryGap','backgroundBlur','backgroundOpacity'].map(k=>MW_FIELD(k,({borderWidth:'Spessore bordo',borderRadius:'Raggio bordo',categoryGap:'Spazio categorie',backgroundBlur:'Sfocatura sfondo',backgroundOpacity:'Opacità sfondo'})[k],'number')),...['borderColor','categoryActiveBackground','categoryActiveText'].map(k=>MW_FIELD(k,({borderColor:'Colore bordo',categoryActiveBackground:'Categoria attiva sfondo',categoryActiveText:'Categoria attiva testo'})[k],'color')),MW_FIELD('categoryAlign','Allineamento categorie','text',{options:['left','center','right']}),MW_FIELD('navigation','Navigazione categorie','text',{options:['tabs','list','drawer']}),MW_FIELD('headerSticky','Header fisso','boolean'),MW_FIELD('logoShape','Forma logo','text',{options:['square','rounded','circle']}),MW_FIELD('backgroundImageUrl','Sfondo immagine URL','text',{nullable:true}),MW_FIELD('backgroundSize','Dimensione sfondo','text',{options:['cover','contain','auto']}),MW_FIELD('backgroundRepeat','Ripetizione sfondo','text',{options:['no-repeat','repeat','repeat-x','repeat-y']}),MW_FIELD('showFoodLegends','Legende alimentari','boolean'),MW_FIELD('reviewUrl','URL recensioni HTTPS','text',{nullable:true}),MW_FIELD('reviewLabel','Testo recensioni')],
 itemFields:[MW_FIELD('name','Nome'),MW_FIELD('description','Descrizione','text',{nullable:true}),MW_FIELD('price','Prezzo','number'),MW_FIELD('costPrice','Costo','number',{nullable:true}),MW_FIELD('imageUrl','Immagine URL','text',{nullable:true}),MW_FIELD('displayMode','Presentazione','text',{options:['normal','centered','link']}),MW_FIELD('externalLink','Link HTTPS','text',{nullable:true}),MW_FIELD('priceDisplay','Prezzo mostrato','text',{nullable:true}),MW_FIELD('kitchenStation','Stazione cucina','text',{nullable:true}),MW_FIELD('prepTimeMinutes','Preparazione minuti','number'),MW_FIELD('calories','Calorie','number',{nullable:true}),MW_FIELD('allergens','Allergeni','list'),MW_FIELD('tags','Caratteristiche','list'),MW_FIELD('additives','Additivi','list'),MW_FIELD('featured','In evidenza','boolean')],
 pdfFields:[MW_FIELD('format','Formato','text',{options:['A4','A5','LETTER']}),MW_FIELD('orientation','Orientamento','text',{options:['portrait','landscape']}),MW_FIELD('columns','Colonne','number'),MW_FIELD('margin','Margine','number'),MW_FIELD('fontSize','Dimensione testo','number'),...['showCover','showImages','showPrices','showDescriptions','showAllergens','showPageNumbers','showQr'].map(k=>MW_FIELD(k,{showCover:'Copertina',showImages:'Immagini',showPrices:'Prezzi',showDescriptions:'Descrizioni',showAllergens:'Allergeni',showPageNumbers:'Numeri pagina',showQr:'QR'}[k],'boolean')),MW_FIELD('footer','Footer'),MW_FIELD('font','Font','text',{options:['sans','serif','mono','poppins','staatliches','amaranth','italiana']}),MW_FIELD('alignment','Allineamento','text',{options:['left','center','right']}),...['categoryPageBreak','nameBold','descriptionItalic','showLogo','showFoodLegends','showMenuName','showDate','includeUnavailable'].map(k=>MW_FIELD(k,({categoryPageBreak:'Categoria su nuova pagina',nameBold:'Nome grassetto',descriptionItalic:'Descrizione corsivo',showLogo:'Logo',showFoodLegends:'Legende alimentari',showMenuName:'Nome menu',showDate:'Data',includeUnavailable:'Includi piatti non disponibili'})[k],'boolean')),...['background','textColor','headingColor'].map(k=>MW_FIELD(k,({background:'Sfondo',textColor:'Colore testo',headingColor:'Colore titoli'})[k],'color')),MW_FIELD('headingFontSize','Dimensione titoli','number'),...['marginTop','marginRight','marginBottom','marginLeft'].map(k=>MW_FIELD(k,({marginTop:'Margine sopra',marginRight:'Margine destro',marginBottom:'Margine sotto',marginLeft:'Margine sinistro'})[k],'number',{nullable:true})),MW_FIELD('logoShape','Forma logo','text',{options:['square','rounded','circle']}),MW_FIELD('translationPolicy','Traduzioni','text',{options:[{value:'fallback',label:'Usa originale se manca'},{value:'translated-only',label:'Solo testi tradotti'}]})]
