function MenuWorkspaceCatalogs({adapter,item,onChange}) {
 const [catalogs,setCatalogs]=useState(null),[error,setError]=useState('');
 useEffect(()=>{adapter.listCatalogs().then(setCatalogs).catch(e=>setError(e.message));},[adapter]);
 return <section><h4>Cataloghi alimentari</h4>{error&&<p role="alert">{error}</p>}{catalogs&&[['allergens','Allergeni','allergens'],['traits','Caratteristiche','tags'],['additives','Additivi','additives']].map(([catalog,label,key])=><fieldset key={key}><legend>{label}</legend><div className="mw-fields">{(catalogs[catalog]||[]).map(c=><label className="mw-check" key={c.id}><input type="checkbox" checked={(item[key]||[]).includes(c.id)} onChange={e=>onChange(key,e.target.checked?[...(item[key]||[]),c.id]:(item[key]||[]).filter(v=>v!==c.id))}/>{c.label}</label>)}</div></fieldset>)}</section>;
}

const MW_SEARCH=(value,query)=>String(value||'').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase());
const MW_ITEM_MATCH=(item,section,query,state)=>((MW_SEARCH(item.name,query)||MW_SEARCH(item.description,query)||MW_SEARCH(section.name,query))&&(state==='all'||(state==='visible'?(section.active!==false&&item.available!==false):(section.active===false||item.available===false))));
const MW_SECTION_MATCH=(section,query,state)=>section.items.some(i=>MW_ITEM_MATCH(i,section,query,state))||((MW_SEARCH(section.name,query)||MW_SEARCH(section.description,query))&&(state==='all'||(state==='visible'?section.active!==false:section.active===false)));
function MenuWorkspaceTree({menu,search,visibility}) {const node=s=><li key={s.id}><button className="press" onClick={()=>window.document.getElementById('mw-section-'+s.id)?.scrollIntoView({block:'start',behavior:'auto'})}>{s.name} <small>({s.items.length})</small></button>{!s.parentSectionId&&<ul>{menu.sections.filter(child=>child.parentSectionId===s.id&&MW_SECTION_MATCH(child,search,visibility)).map(node)}</ul>}</li>;return <nav aria-label="Albero categorie" className="mw-tree"><ul>{menu.sections.filter(s=>!s.parentSectionId&&(MW_SECTION_MATCH(s,search,visibility)||menu.sections.some(c=>c.parentSectionId===s.id&&MW_SECTION_MATCH(c,search,visibility)))).map(node)}</ul>{!menu.sections.some(s=>MW_SECTION_MATCH(s,search,visibility))&&<p>Nessun contenuto corrisponde ai filtri.</p>}</nav>;}
const MW_TRANSLATION_STATUS=(doc,language)=>{const entities=doc.menus.flatMap(m=>[m,...m.sections.flatMap(s=>[s,...s.items])]);let total=0,complete=0;for(const entity of entities){total++;if(entity.translations?.[language]?.name?.trim())complete++;if(entity.description?.trim()){total++;if(entity.translations?.[language]?.description?.trim())complete++;}}return {total,complete,missing:total-complete};};
function MenuWorkspaceTranslationStatus({document}) {return <table className="mw-status"><thead><tr><th>Lingua</th><th>Completati</th><th>Mancanti</th></tr></thead><tbody>{document.languages.map(l=>{const s=MW_TRANSLATION_STATUS(document,l);return <tr key={l}><td>{l}{l===document.defaultLanguage?' · originale':''}</td><td>{l===document.defaultLanguage?s.total:s.complete} / {s.total}</td><td>{l===document.defaultLanguage?0:s.missing}</td></tr>})}</tbody></table>;}

function MenuWorkspaceDiff({diff}) {const value=v=>v===null||v===undefined?'—':typeof v==='object'?JSON.stringify(v):String(v);return <section className="mw-diff"><h4>Confronto bozza corrente → versione selezionata</h4>{diff.details?.length?diff.details.map(change=><div key={change.id}><h5>{({added:'Aggiunto',removed:'Rimosso',changed:'Modificato'})[change.action]} · {change.label}</h5><table className="mw-status"><thead><tr><th>Campo</th><th>Bozza corrente</th><th>Versione selezionata</th></tr></thead><tbody>{change.fields?.length?change.fields.map(field=><tr key={field.field}><td>{field.label||field.field}</td><td>{value(field.before)}</td><td>{value(field.after)}</td></tr>):<tr><td>Contenuto</td><td>{value(change.before)}</td><td>{value(change.after)}</td></tr>}</tbody></table></div>):<p>{diff.added.length} aggiunti · {diff.removed.length} rimossi · {diff.changed.length} modificati</p>}</section>;}

